import{_ as a,b as n,f as e,I as t}from"./chunks/framework.DYvp_Vyw.js";const b=JSON.parse('{"title":"Java期末复习笔记 - 第三章 - Java语言基础","description":"","frontmatter":{"title":"Java期末复习笔记 - 第三章 - Java语言基础","date":"2025-05-07T01:50:13.000Z","tags":["Java"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Java-Own-Study-003.md","filePath":"posts/Java-Own-Study-003.md"}'),l={name:"posts/Java-Own-Study-003.md"};function o(p,s,d,c,r,i){return e(),n("div",null,s[0]||(s[0]=[t(`<p>大二上学期的期末复习笔记。</p><hr><div style="text-align:center;"><h1>Java语言基础</h1></div><h1 id="_1-数据类型" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">1.数据类型 </u> <a class="header-anchor" href="#_1-数据类型" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;1.数据类型 &lt;/u&gt;&quot;">​</a></h1><p>1.在程序设计中，数据是程序的必要组成部分，也是程序处理的对象。</p><p>2.Java中的数据类型分为两大类，一类是基本数据类型，简称基本类型；另一类是引用和数据类型，简称引用类型。</p><blockquote><p>基本数据类型在内存中存放的是数据值本身。引用数据类型在内存中存放的是指向该数据的地址，而不是数据值本身。</p></blockquote><blockquote><p>引用数据类型在内存中存放的是指向该数据的地址，而不是数据值本身，它往往由多个基本数据类型组成。</p></blockquote><blockquote><p>基本数据类型有整数型、浮点型、布尔型和字符型。 引用数据类型包括数组、类和接口等。</p></blockquote><p>3.Java定义了4类共8种基本类型，其中有4种整数型、2种浮点型、1种布尔型和1种字符型。</p><blockquote><p>整数型：byte、short、int、long 浮点型：float、double 布尔型：boolean 字符型：char</p></blockquote><p>4.Java语言的基本数据类型表</p><table tabindex="0"><thead><tr><th>数据类型</th><th>关键字</th><th>占用字节数</th><th>默认数值</th><th>取值范围</th></tr></thead><tbody><tr><td>整数类型</td><td></td><td></td><td></td><td></td></tr><tr><td>byte</td><td><code>byte</code></td><td>1</td><td>0</td><td>-128 到 127</td></tr><tr><td>short</td><td><code>short</code></td><td>2</td><td>0</td><td>-32,768 到 32,767</td></tr><tr><td>int</td><td><code>int</code></td><td>4</td><td>0</td><td>-2,147,483,648 到 2,147,483,647</td></tr><tr><td>long</td><td><code>long</code></td><td>8</td><td>0L</td><td>-9,223,372,036,854,775,808 到 9,223,372,036,854,775,807</td></tr><tr><td>浮点类型</td><td></td><td></td><td></td><td></td></tr><tr><td>float</td><td><code>float</code></td><td>4</td><td>0.0f</td><td>±1.4E-45 到 ±3.4E+38</td></tr><tr><td>double</td><td><code>double</code></td><td>8</td><td>0.0d</td><td>±4.9E-324 到 ±1.8E+308</td></tr><tr><td>字符类型</td><td></td><td></td><td></td><td></td></tr><tr><td>char</td><td><code>char</code></td><td>2</td><td>&#39;\\u0000&#39;</td><td>0 到 65,535（Unicode 字符集）</td></tr><tr><td>布尔类型</td><td></td><td></td><td></td><td></td></tr><tr><td>boolean</td><td><code>boolean</code></td><td>1</td><td>false</td><td>true 或 false</td></tr></tbody></table><p>5.数值型常量的特殊值代码</p><table tabindex="0"><thead><tr><th>数据类型</th><th>所在的类</th><th>最小值代码</th><th>最大值代码</th></tr></thead><tbody><tr><td>byte</td><td><code>Byte</code></td><td><code>Byte.MIN_VALUE</code></td><td><code>Byte.MAX_VALUE</code></td></tr><tr><td>short</td><td><code>Short</code></td><td><code>Short.MIN_VALUE</code></td><td><code>Short.MAX_VALUE</code></td></tr><tr><td>int</td><td><code>Integer</code></td><td><code>Integer.MIN_VALUE</code></td><td><code>Integer.MAX_VALUE</code></td></tr><tr><td>long</td><td><code>Long</code></td><td><code>Long.MIN_VALUE</code></td><td><code>Long.MAX_VALUE</code></td></tr><tr><td>float</td><td><code>Float</code></td><td><code>Float.MIN_VALUE</code></td><td><code>Float.MAX_VALUE</code></td></tr><tr><td>double</td><td><code>Double</code></td><td><code>Double.MIN_VALUE</code></td><td><code>Double.MAX_VALUE</code></td></tr></tbody></table><h1 id="_2-关键字与标识符" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">2.关键字与标识符 </u> <a class="header-anchor" href="#_2-关键字与标识符" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;2.关键字与标识符 &lt;/u&gt;&quot;">​</a></h1><h3 id="_2-1-关键字" tabindex="-1">2.1 关键字 <a class="header-anchor" href="#_2-1-关键字" aria-label="Permalink to &quot;2.1 关键字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关键字</th><th>说明</th></tr></thead><tbody><tr><td><code>abstract</code></td><td>声明抽象类或抽象方法</td></tr><tr><td><code>assert</code></td><td>用于调试的断言语句</td></tr><tr><td><code>boolean</code></td><td>关键字用于声明布尔类型</td></tr><tr><td><code>break</code></td><td>终止循环或 switch 语句</td></tr><tr><td><code>byte</code></td><td>关键字用于声明字节类型</td></tr><tr><td><code>case</code></td><td>switch 语句中的一个分支</td></tr><tr><td><code>catch</code></td><td>捕获异常的代码块</td></tr><tr><td><code>char</code></td><td>关键字用于声明字符类型</td></tr><tr><td><code>class</code></td><td>声明类</td></tr><tr><td><code>const</code></td><td>保留字，未使用</td></tr><tr><td><code>continue</code></td><td>跳过当前循环的剩余部分，进入下一次循环</td></tr><tr><td><code>default</code></td><td>switch 语句的默认分支</td></tr><tr><td><code>do</code></td><td>进行 do-while 循环</td></tr><tr><td><code>double</code></td><td>关键字用于声明双精度浮点类型</td></tr><tr><td><code>else</code></td><td>if 语句的另一分支</td></tr><tr><td><code>enum</code></td><td>定义枚举类型</td></tr><tr><td><code>extends</code></td><td>表示继承关系</td></tr><tr><td><code>final</code></td><td>声明常量、不可重写的方法或不可继承的类</td></tr><tr><td><code>finally</code></td><td>在异常处理后执行的代码块</td></tr><tr><td><code>float</code></td><td>关键字用于声明单精度浮点类型</td></tr><tr><td><code>for</code></td><td>进行 for 循环</td></tr><tr><td><code>goto</code></td><td>保留字，未使用</td></tr><tr><td><code>if</code></td><td>条件语句</td></tr><tr><td><code>implements</code></td><td>实现接口</td></tr><tr><td><code>import</code></td><td>导入其他类或包</td></tr><tr><td><code>instanceof</code></td><td>检查对象是否是特定类的实例</td></tr><tr><td><code>int</code></td><td>关键字用于声明整型</td></tr><tr><td><code>interface</code></td><td>声明接口</td></tr><tr><td><code>long</code></td><td>关键字用于声明长整型</td></tr><tr><td><code>native</code></td><td>声明本地方法</td></tr><tr><td><code>new</code></td><td>创建对象</td></tr><tr><td><code>null</code></td><td>表示空值</td></tr><tr><td><code>package</code></td><td>声明包</td></tr><tr><td><code>private</code></td><td>声明私有成员</td></tr><tr><td><code>protected</code></td><td>声明受保护成员</td></tr><tr><td><code>public</code></td><td>声明公共成员</td></tr><tr><td><code>return</code></td><td>从方法返回值</td></tr><tr><td><code>short</code></td><td>关键字用于声明短整型</td></tr><tr><td><code>static</code></td><td>声明静态成员</td></tr><tr><td><code>strictfp</code></td><td>精确浮点计算</td></tr><tr><td><code>super</code></td><td>引用父类的成员</td></tr><tr><td><code>switch</code></td><td>多分支选择语句</td></tr><tr><td><code>synchronized</code></td><td>声明同步方法或代码块</td></tr><tr><td><code>this</code></td><td>引用当前对象</td></tr><tr><td><code>throw</code></td><td>抛出异常</td></tr><tr><td><code>throws</code></td><td>声明方法可能抛出的异常</td></tr><tr><td><code>transient</code></td><td>声明不序列化的成员</td></tr><tr><td><code>try</code></td><td>捕获异常的代码块</td></tr><tr><td><code>void</code></td><td>声明无返回值的方法</td></tr><tr><td><code>volatile</code></td><td>声明易变的变量</td></tr></tbody></table><h3 id="_2-2-标识符" tabindex="-1">2.2 标识符 <a class="header-anchor" href="#_2-2-标识符" aria-label="Permalink to &quot;2.2 标识符&quot;">​</a></h3><p>标识符是用来表示变量名、类名、方法名、数组名和文件名等的有效字符序列。</p><p>1.Java的标识符命名规则 (1):标识符可以由字母、数字和下划线、美元符号等组合而成。 (2):标识符必须以字母、下划线或美元符号开头，不能以数字开头。</p><h1 id="_3-常量" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">3.常量</u> <a class="header-anchor" href="#_3-常量" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;3.常量&lt;/u&gt;&quot;">​</a></h1><h3 id="_3-1-定义" tabindex="-1">3.1 定义 <a class="header-anchor" href="#_3-1-定义" aria-label="Permalink to &quot;3.1 定义&quot;">​</a></h3><p>常量是指在程序执行过程中，其值不能改变的量。在 Java 中，常量的值在声明时被初始化后不可被修改。</p><h3 id="_3-2-关键字" tabindex="-1">3.2 关键字 <a class="header-anchor" href="#_3-2-关键字" aria-label="Permalink to &quot;3.2 关键字&quot;">​</a></h3><p>Java 使用 <code>final</code> 关键字来声明常量。使用 <code>final</code> 修饰的变量在初始化后，不能再被赋值。</p><h3 id="_3-3-声明常量的语法" tabindex="-1">3.3 声明常量的语法 <a class="header-anchor" href="#_3-3-声明常量的语法" aria-label="Permalink to &quot;3.3 声明常量的语法&quot;">​</a></h3><p>常量的声明通常遵循以下语法：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>final 数据类型 常量名 = 常量值;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-4-命名约定" tabindex="-1">3.4 命名约定 <a class="header-anchor" href="#_3-4-命名约定" aria-label="Permalink to &quot;3.4 命名约定&quot;">​</a></h3><ul><li>常量名通常使用全大写字母，单词之间用下划线分隔。例如：<code>MAX_VALUE</code>、<code>PI</code>。</li></ul><h3 id="_3-5-常量的类型" tabindex="-1">3.5 常量的类型 <a class="header-anchor" href="#_3-5-常量的类型" aria-label="Permalink to &quot;3.5 常量的类型&quot;">​</a></h3><ul><li><p><strong>基本数据类型常量</strong>: 如 <code>int</code>、<code>float</code>、<code>double</code> 等。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>final int MAX_AGE = 100;</span></span>
<span class="line"><span>final double PI = 3.14159;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p><strong>引用类型常量</strong>: 如字符串常量。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>final String GREETING = &quot;Hello, World!&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h3 id="_3-6-使用常量的优点" tabindex="-1">3.6 使用常量的优点 <a class="header-anchor" href="#_3-6-使用常量的优点" aria-label="Permalink to &quot;3.6 使用常量的优点&quot;">​</a></h3><ul><li><strong>可读性</strong>: 使用常量可以使代码更具可读性，表达意图更清晰。</li><li><strong>维护性</strong>: 修改常量的值只需在一个地方进行，减少了出错的可能性。</li><li><strong>避免魔法数字</strong>: 使用常量可以避免在代码中出现难以理解的数字或字符串。</li></ul><h3 id="_3-7-示例代码" tabindex="-1">3.7 示例代码 <a class="header-anchor" href="#_3-7-示例代码" aria-label="Permalink to &quot;3.7 示例代码&quot;">​</a></h3><p>以下是使用常量的示例：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>public class Circle {</span></span>
<span class="line"><span>    public static final double PI = 3.14159; // 圆周率常量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static double calculateArea(double radius) {</span></span>
<span class="line"><span>        return PI * radius * radius; // 使用常量</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_3-8-java的常用转义字符表" tabindex="-1">3.8 Java的常用转义字符表 <a class="header-anchor" href="#_3-8-java的常用转义字符表" aria-label="Permalink to &quot;3.8 Java的常用转义字符表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>转义字符</th><th>描述</th><th>Unicode 值</th></tr></thead><tbody><tr><td><code>\\&#39;</code></td><td>单引号</td><td><code>\\u0027</code></td></tr><tr><td><code>\\&quot;</code></td><td>双引号</td><td><code>\\u0022</code></td></tr><tr><td><code>\\\\</code></td><td>反斜杠</td><td><code>\\u005C</code></td></tr><tr><td><code>\\n</code></td><td>换行符</td><td><code>\\u000A</code></td></tr><tr><td><code>\\r</code></td><td>回车符</td><td><code>\\u000D</code></td></tr><tr><td><code>\\t</code></td><td>制表符（Tab）</td><td><code>\\u0009</code></td></tr><tr><td><code>\\b</code></td><td>退格符</td><td><code>\\u0008</code></td></tr><tr><td><code>\\f</code></td><td>换页符</td><td><code>\\u000C</code></td></tr><tr><td><code>\\0</code></td><td>空字符（null character）</td><td><code>\\u0000</code></td></tr><tr><td><code>\\uXXXX</code></td><td>Unicode 字符（<code>XXXX</code> 是四位十六进制数字）</td><td><code>\\uXXXX</code></td></tr></tbody></table><h1 id="_4-变量" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">4.变量</u> <a class="header-anchor" href="#_4-变量" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;4.变量&lt;/u&gt;&quot;">​</a></h1><h3 id="_4-1-定义" tabindex="-1">4.1 定义 <a class="header-anchor" href="#_4-1-定义" aria-label="Permalink to &quot;4.1 定义&quot;">​</a></h3><p>变量是程序中用于存储数据的命名内存位置。每个变量都有一个特定的数据类型，决定了可以存储何种类型的数据。</p><h3 id="_4-2-变量的类型" tabindex="-1">4.2 变量的类型 <a class="header-anchor" href="#_4-2-变量的类型" aria-label="Permalink to &quot;4.2 变量的类型&quot;">​</a></h3><p>Java 中的变量主要分为两种类型：</p><ul><li><strong>基本数据类型变量</strong>: 存储基本数据类型的值，包括： <ul><li><code>int</code>、<code>float</code>、<code>double</code>、<code>char</code>、<code>boolean</code> 等。</li></ul></li><li><strong>引用类型变量</strong>: 存储对象的引用，包括： <ul><li>自定义类、数组、接口等。</li></ul></li></ul><h3 id="_4-3-变量的声明和初始化" tabindex="-1">4.3 变量的声明和初始化 <a class="header-anchor" href="#_4-3-变量的声明和初始化" aria-label="Permalink to &quot;4.3 变量的声明和初始化&quot;">​</a></h3><p>变量的声明和初始化通常遵循以下语法：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>数据类型 变量名;          // 声明变量</span></span>
<span class="line"><span>变量名 = 值;             // 初始化变量</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>可以在一行中同时声明和初始化变量：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>数据类型 变量名 = 值;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_4-4-变量的命名规则" tabindex="-1">4.4 变量的命名规则 <a class="header-anchor" href="#_4-4-变量的命名规则" aria-label="Permalink to &quot;4.4 变量的命名规则&quot;">​</a></h3><ul><li>变量名可以包含字母、数字、下划线和美元符号，但不能以数字开头。</li><li>变量名不能是 Java 的关键字。</li><li>变量名应具有描述性，以提高代码可读性。</li></ul><h3 id="_4-5-变量的作用域" tabindex="-1">4.5 变量的作用域 <a class="header-anchor" href="#_4-5-变量的作用域" aria-label="Permalink to &quot;4.5 变量的作用域&quot;">​</a></h3><p>变量的作用域决定了它在程序中的可见性和生命周期：</p><ul><li><p><strong>局部变量</strong>: 在方法或代码块内部声明的变量，只能在该方法或代码块内部访问。</p></li><li><p><strong>实例变量</strong>: 在类中声明的变量，每个对象都有自己的副本。</p></li><li><p><strong>类变量（静态变量）</strong>: 使用 <code>static</code> 关键字声明的变量，属于类而不是某个对象，所有对象共享同一副本。</p></li></ul><h3 id="_4-6-示例代码" tabindex="-1">4.6 示例代码 <a class="header-anchor" href="#_4-6-示例代码" aria-label="Permalink to &quot;4.6 示例代码&quot;">​</a></h3><p>以下是一个简单的示例，演示了变量的声明、初始化和使用：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>public class VariableExample {</span></span>
<span class="line"><span>    // 类变量</span></span>
<span class="line"><span>    static int classVariable = 10;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 实例变量</span></span>
<span class="line"><span>    int instanceVariable;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public VariableExample(int value) {</span></span>
<span class="line"><span>        // 初始化实例变量</span></span>
<span class="line"><span>        this.instanceVariable = value;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public void displayVariables() {</span></span>
<span class="line"><span>        // 局部变量</span></span>
<span class="line"><span>        int localVariable = 5;</span></span>
<span class="line"><span>        System.out.println(&quot;Class Variable: &quot; + classVariable);</span></span>
<span class="line"><span>        System.out.println(&quot;Instance Variable: &quot; + instanceVariable);</span></span>
<span class="line"><span>        System.out.println(&quot;Local Variable: &quot; + localVariable);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        VariableExample example = new VariableExample(20);</span></span>
<span class="line"><span>        example.displayVariables();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><h1 id="_5-数据类型之间的转换" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">5.数据类型之间的转换</u> <a class="header-anchor" href="#_5-数据类型之间的转换" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;5.数据类型之间的转换&lt;/u&gt;&quot;">​</a></h1><h3 id="_5-1-数据类型分类" tabindex="-1">5.1 数据类型分类 <a class="header-anchor" href="#_5-1-数据类型分类" aria-label="Permalink to &quot;5.1 数据类型分类&quot;">​</a></h3><p>Java 中的数据类型主要分为两种：</p><ul><li><strong>基本数据类型</strong>: 包括 <code>byte</code>、<code>short</code>、<code>int</code>、<code>long</code>、<code>float</code>、<code>double</code>、<code>char</code> 和 <code>boolean</code>。</li><li><strong>引用数据类型</strong>: 包括对象、数组和字符串。</li></ul><h3 id="_5-2-转换类型" tabindex="-1">5.2 转换类型 <a class="header-anchor" href="#_5-2-转换类型" aria-label="Permalink to &quot;5.2 转换类型&quot;">​</a></h3><p>在 Java 中，数据类型之间的转换主要分为两种类型：</p><h4 id="_5-2-1-自动类型转换-隐式转换" tabindex="-1">5.2.1 自动类型转换（隐式转换） <a class="header-anchor" href="#_5-2-1-自动类型转换-隐式转换" aria-label="Permalink to &quot;5.2.1 自动类型转换（隐式转换）&quot;">​</a></h4><p>自动类型转换发生在一种数据类型的值被赋给另一种更大范围的数据类型时，Java 会自动进行转换。例如：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>int intValue = 100;</span></span>
<span class="line"><span>long longValue = intValue; // int 转换为 long</span></span>
<span class="line"><span>float floatValue = longValue; // long 转换为 float</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>注意事项</strong>:</p><ul><li>自动转换不会导致数据丢失。</li><li>只能在兼容类型之间进行自动转换。</li></ul><blockquote><p>转换的优先级： <code>byte → short → char → int → long → float → double</code><code>boolean</code>因为只能存放true和false，与整数型及字符型不兼容，因此不可能做类型转换。</p></blockquote><blockquote><p>在一个表达式中若有整数型为short或byte的数据参加计算，为了避免溢出，Java会将表达式中的short和byte类型的数据自动转换为int类型。</p></blockquote><blockquote><p>值得注意的是，类型的转换只限该语句本身，并不会影响原先变量的类型定义，而且通过自动类型转换可以保证数据的精确度，它不会因为类型转换而损失数据的内容。</p></blockquote><h4 id="_5-2-2-强制类型转换-显式转换" tabindex="-1">5.2.2 强制类型转换（显式转换） <a class="header-anchor" href="#_5-2-2-强制类型转换-显式转换" aria-label="Permalink to &quot;5.2.2 强制类型转换（显式转换）&quot;">​</a></h4><p>强制类型转换发生在一种数据类型的值被赋给另一种更小范围的数据类型时，必须使用强制转换操作符。格式如下：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#839496;">数据类型 变量名 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (目标数据类型) 值;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例如：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">double</span><span style="color:#268BD2;"> doubleValue</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 9.78</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#839496;">) doubleValue; </span><span style="color:#586E75;font-style:italic;">// double 转换为 int，结果为 9</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>注意事项</strong>:</p><ul><li>强制转换可能导致数据丢失或精度下降。</li><li>只能在兼容类型之间进行强制转换。</li></ul><h3 id="_5-3-特殊转换" tabindex="-1">5.3. 特殊转换 <a class="header-anchor" href="#_5-3-特殊转换" aria-label="Permalink to &quot;5.3. 特殊转换&quot;">​</a></h3><ul><li><p><strong>字符与整数之间的转换</strong>:</p><ul><li><p>可以将字符类型转换为整数类型，表示其 Unicode 值。</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">char</span><span style="color:#268BD2;"> charValue</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &#39;A&#39;</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> charValue; </span><span style="color:#586E75;font-style:italic;">// A 的 Unicode 值为 65</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>反之，整数也可以转换为字符：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 65</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">char</span><span style="color:#268BD2;"> charValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">char</span><span style="color:#839496;">) intValue; </span><span style="color:#586E75;font-style:italic;">// 转换为字符 &#39;A&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li></ul></li><li><p><strong>字符串与基本数据类型之间的转换</strong>:</p><ul><li><p>字符串可以通过包装类的方法转换为基本数据类型：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#268BD2;"> strValue</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &quot;123&quot;</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> Integer</span><span style="color:#839496;">.</span><span style="color:#268BD2;">parseInt</span><span style="color:#839496;">(strValue); </span><span style="color:#586E75;font-style:italic;">// 字符串转换为 int</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>反之，可以使用 <code>String.valueOf()</code> 方法将基本数据类型转换为字符串：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 123</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#268BD2;"> strValue</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> String</span><span style="color:#839496;">.</span><span style="color:#268BD2;">valueOf</span><span style="color:#839496;">(intValue); </span><span style="color:#586E75;font-style:italic;">// int 转换为字符串</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li></ul></li></ul><blockquote><p>字符串转换为数值型数据的方法</p></blockquote><table tabindex="0"><thead><tr><th>转换方法</th><th>功能说明</th></tr></thead><tbody><tr><td><code>Integer.parseInt(String s)</code></td><td>将字符串转换为 <code>int</code> 类型</td></tr><tr><td><code>Long.parseLong(String s)</code></td><td>将字符串转换为 <code>long</code> 类型</td></tr><tr><td><code>Float.parseFloat(String s)</code></td><td>将字符串转换为 <code>float</code> 类型</td></tr><tr><td><code>Double.parseDouble(String s)</code></td><td>将字符串转换为 <code>double</code> 类型</td></tr><tr><td><code>Short.parseShort(String s)</code></td><td>将字符串转换为 <code>short</code> 类型</td></tr><tr><td><code>Byte.parseByte(String s)</code></td><td>将字符串转换为 <code>byte</code> 类型</td></tr><tr><td><code>Boolean.parseBoolean(String s)</code></td><td>将字符串转换为 <code>boolean</code> 类型，&quot;true&quot;（不区分大小写）返回 <code>true</code>，其他返回 <code>false</code></td></tr></tbody></table><h3 id="_5-4-示例代码" tabindex="-1">5.4 示例代码 <a class="header-anchor" href="#_5-4-示例代码" aria-label="Permalink to &quot;5.4 示例代码&quot;">​</a></h3><p>以下是一个示例，展示了不同类型的转换：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">public</span><span style="color:#93A1A1;font-weight:bold;"> class</span><span style="color:#CB4B16;"> TypeConversionExample</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    public</span><span style="color:#93A1A1;font-weight:bold;"> static</span><span style="color:#93A1A1;font-weight:bold;"> void</span><span style="color:#268BD2;"> main</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">[] args) {</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 自动转换</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        int</span><span style="color:#268BD2;"> intValue</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 100</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        long</span><span style="color:#268BD2;"> longValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> intValue; </span><span style="color:#586E75;font-style:italic;">// 自动转换</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Long Value: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> longValue);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 强制转换</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        double</span><span style="color:#268BD2;"> doubleValue</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 9.78</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        int</span><span style="color:#268BD2;"> convertedValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> (</span><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#839496;">) doubleValue; </span><span style="color:#586E75;font-style:italic;">// 强制转换</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Converted Int Value: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> convertedValue);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 字符与整数转换</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        char</span><span style="color:#268BD2;"> charValue</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &#39;A&#39;</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        int</span><span style="color:#268BD2;"> unicodeValue</span><span style="color:#859900;"> =</span><span style="color:#839496;"> charValue; </span><span style="color:#586E75;font-style:italic;">// char 转 int</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Unicode Value of &#39;A&#39;: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> unicodeValue);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 字符串与基本数据类型转换</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        String</span><span style="color:#268BD2;"> strValue</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &quot;123&quot;</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        int</span><span style="color:#268BD2;"> parsedValue</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> Integer</span><span style="color:#839496;">.</span><span style="color:#268BD2;">parseInt</span><span style="color:#839496;">(strValue); </span><span style="color:#586E75;font-style:italic;">// 字符串转 int</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Parsed Int Value: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> parsedValue);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        String</span><span style="color:#268BD2;"> fromInt</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> String</span><span style="color:#839496;">.</span><span style="color:#268BD2;">valueOf</span><span style="color:#839496;">(parsedValue); </span><span style="color:#586E75;font-style:italic;">// int 转字符串</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;String from Int: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> fromInt);</span></span>
<span class="line"><span style="color:#839496;">    }</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><h1 id="_6-局部变量的类型推断" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">6.局部变量的类型推断</u> <a class="header-anchor" href="#_6-局部变量的类型推断" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;6.局部变量的类型推断&lt;/u&gt;&quot;">​</a></h1><h3 id="_6-1-定义" tabindex="-1">6.1 定义 <a class="header-anchor" href="#_6-1-定义" aria-label="Permalink to &quot;6.1 定义&quot;">​</a></h3><p>局部变量类型推断是 Java 10 引入的一项特性，允许编译器根据变量初始化时的值自动推断变量的类型，而不需要显式声明类型。</p><h3 id="_6-2-使用-var-关键字" tabindex="-1">6.2 使用 <code>var</code> 关键字 <a class="header-anchor" href="#_6-2-使用-var-关键字" aria-label="Permalink to &quot;6.2 使用 \`var\` 关键字&quot;">​</a></h3><p>在局部变量声明时，使用 <code>var</code> 关键字来代替具体的数据类型。编译器根据赋值的右侧表达式来推断变量的类型。</p><h3 id="_6-3-示例" tabindex="-1">6.3 示例 <a class="header-anchor" href="#_6-3-示例" aria-label="Permalink to &quot;6.3 示例&quot;">​</a></h3><p>以下是局部变量类型推断的使用示例：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#93A1A1;font-weight:bold;">public</span><span style="color:#93A1A1;font-weight:bold;"> class</span><span style="color:#CB4B16;"> VarExample</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    public</span><span style="color:#93A1A1;font-weight:bold;"> static</span><span style="color:#93A1A1;font-weight:bold;"> void</span><span style="color:#268BD2;"> main</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">[] args) {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> number</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 10</span><span style="color:#839496;">;          </span><span style="color:#586E75;font-style:italic;">// 推断为 int</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> name</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &quot;Java&quot;</span><span style="color:#839496;">;        </span><span style="color:#586E75;font-style:italic;">// 推断为 String</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> pi</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 3.14</span><span style="color:#839496;">;           </span><span style="color:#586E75;font-style:italic;">// 推断为 double</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> list</span><span style="color:#859900;"> =</span><span style="color:#859900;"> new</span><span style="color:#93A1A1;font-weight:bold;"> ArrayList</span><span style="color:#839496;">&lt;</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">&gt;(); </span><span style="color:#586E75;font-style:italic;">// 推断为 ArrayList&lt;String&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Number: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> number);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Name: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> name);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Pi: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> pi);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;List: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> list);</span></span>
<span class="line"><span style="color:#839496;">    }</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h3 id="_6-4-注意事项" tabindex="-1">6.4 注意事项 <a class="header-anchor" href="#_6-4-注意事项" aria-label="Permalink to &quot;6.4 注意事项&quot;">​</a></h3><ul><li><p><strong>局部变量</strong>: <code>var</code> 只能用于局部变量，不能用于成员变量、方法参数或返回类型。</p></li><li><p><strong>初始化</strong>: 使用 <code>var</code> 声明的变量必须在同一行进行初始化，编译器才能推断其类型。</p></li><li><p><strong>类型推断</strong>: 一旦推断出类型，变量的类型在其作用域内是固定的，不能再改变。</p></li><li><p><strong>可读性</strong>: 虽然 <code>var</code> 提高了代码的简洁性，但过度使用可能会降低代码的可读性，特别是在复杂表达式中。</p></li></ul><h3 id="_6-5-示例代码" tabindex="-1">6.5 示例代码 <a class="header-anchor" href="#_6-5-示例代码" aria-label="Permalink to &quot;6.5 示例代码&quot;">​</a></h3><p>以下是使用 <code>var</code> 关键字的示例代码，展示了类型推断的优势和限制：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">import</span><span style="color:#93A1A1;font-weight:bold;"> java.util.ArrayList</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">public</span><span style="color:#93A1A1;font-weight:bold;"> class</span><span style="color:#CB4B16;"> VarExample</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    public</span><span style="color:#93A1A1;font-weight:bold;"> static</span><span style="color:#93A1A1;font-weight:bold;"> void</span><span style="color:#268BD2;"> main</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">[] args) {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> number</span><span style="color:#859900;"> =</span><span style="color:#D33682;"> 100</span><span style="color:#839496;">; </span><span style="color:#586E75;font-style:italic;">// int</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> name</span><span style="color:#859900;"> =</span><span style="color:#2AA198;"> &quot;Hello&quot;</span><span style="color:#839496;">; </span><span style="color:#586E75;font-style:italic;">// String</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        var</span><span style="color:#268BD2;"> list</span><span style="color:#859900;"> =</span><span style="color:#859900;"> new</span><span style="color:#93A1A1;font-weight:bold;"> ArrayList</span><span style="color:#839496;">&lt;</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">&gt;(); </span><span style="color:#586E75;font-style:italic;">// ArrayList&lt;String&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 不能使用 var 进行未初始化的声明</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // var uninitialized;</span><span style="color:#586E75;font-style:italic;"> // 错误: 不能推断类型</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 输出变量</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Number: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> number);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;Name: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> name);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;List: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> list);</span></span>
<span class="line"><span style="color:#839496;">    }</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h1 id="_7-从键盘输入数据" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">7.从键盘输入数据</u> <a class="header-anchor" href="#_7-从键盘输入数据" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;7.从键盘输入数据&lt;/u&gt;&quot;">​</a></h1><h3 id="_7-1-使用-scanner-类" tabindex="-1">7.1 使用 <code>Scanner</code> 类 <a class="header-anchor" href="#_7-1-使用-scanner-类" aria-label="Permalink to &quot;7.1 使用 \`Scanner\` 类&quot;">​</a></h3><p>在 Java 中，可以使用 <code>Scanner</code> 类从键盘输入数据。<code>Scanner</code> 类位于 <code>java.util</code> 包中，提供了多种方法来读取不同类型的数据。</p><h3 id="_7-2-引入-scanner-类" tabindex="-1">7.2 引入 <code>Scanner</code> 类 <a class="header-anchor" href="#_7-2-引入-scanner-类" aria-label="Permalink to &quot;7.2 引入 \`Scanner\` 类&quot;">​</a></h3><p>在使用 <code>Scanner</code> 之前，首先需要导入它：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">import</span><span style="color:#93A1A1;font-weight:bold;"> java.util.Scanner</span><span style="color:#839496;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_7-3-创建-scanner-对象" tabindex="-1">7.3 创建 <code>Scanner</code> 对象 <a class="header-anchor" href="#_7-3-创建-scanner-对象" aria-label="Permalink to &quot;7.3 创建 \`Scanner\` 对象&quot;">​</a></h3><p>通过 <code>new</code> 关键字创建 <code>Scanner</code> 对象，并将 <code>System.in</code> 作为参数传入，以便从标准输入流（键盘）读取数据：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>Scanner scanner = new Scanner(System.in);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_7-4-读取输入数据" tabindex="-1">7.4 读取输入数据 <a class="header-anchor" href="#_7-4-读取输入数据" aria-label="Permalink to &quot;7.4 读取输入数据&quot;">​</a></h3><p><code>Scanner</code> 类提供了多种方法来读取不同类型的数据：</p><ul><li><code>nextLine()</code>: 读取一行字符串</li><li><code>next()</code>: 读取一个单词（空格分隔）</li><li><code>nextInt()</code>: 读取一个整数</li><li><code>nextDouble()</code>: 读取一个双精度浮点数</li><li><code>nextBoolean()</code>: 读取一个布尔值</li></ul><blockquote><p>详细表</p></blockquote><table tabindex="0"><thead><tr><th>方法</th><th>功能说明</th><th>示例代码</th></tr></thead><tbody><tr><td><code>nextLine()</code></td><td>读取输入的一整行，返回字符串</td><td><code>String line = scanner.nextLine();</code></td></tr><tr><td><code>next()</code></td><td>读取下一个完整的单词，返回字符串</td><td><code>String word = scanner.next();</code></td></tr><tr><td><code>nextInt()</code></td><td>读取下一个整数，返回 <code>int</code> 类型</td><td><code>int number = scanner.nextInt();</code></td></tr><tr><td><code>nextDouble()</code></td><td>读取下一个双精度浮点数，返回 <code>double</code> 类型</td><td><code>double value = scanner.nextDouble();</code></td></tr><tr><td><code>nextFloat()</code></td><td>读取下一个单精度浮点数，返回 <code>float</code> 类型</td><td><code>float fValue = scanner.nextFloat();</code></td></tr><tr><td><code>nextLong()</code></td><td>读取下一个长整型数，返回 <code>long</code> 类型</td><td><code>long longValue = scanner.nextLong();</code></td></tr><tr><td><code>nextShort()</code></td><td>读取下一个短整型数，返回 <code>short</code> 类型</td><td><code>short shortValue = scanner.nextShort();</code></td></tr><tr><td><code>nextByte()</code></td><td>读取下一个字节型数，返回 <code>byte</code> 类型</td><td><code>byte byteValue = scanner.nextByte();</code></td></tr><tr><td><code>nextBoolean()</code></td><td>读取下一个布尔值，返回 <code>boolean</code> 类型</td><td><code>boolean boolValue = scanner.nextBoolean();</code></td></tr><tr><td><code>hasNextLine()</code></td><td>检查是否还有下一行输入</td><td><code>if (scanner.hasNextLine()) { ... }</code></td></tr><tr><td><code>hasNext()</code></td><td>检查是否还有下一个完整的单词</td><td><code>if (scanner.hasNext()) { ... }</code></td></tr><tr><td><code>hasNextInt()</code></td><td>检查下一个输入是否为整数</td><td><code>if (scanner.hasNextInt()) { ... }</code></td></tr><tr><td><code>hasNextDouble()</code></td><td>检查下一个输入是否为双精度浮点数</td><td><code>if (scanner.hasNextDouble()) { ... }</code></td></tr><tr><td><code>close()</code></td><td>关闭 <code>Scanner</code> 对象，释放资源</td><td><code>scanner.close();</code></td></tr></tbody></table><h3 id="_7-5-示例代码" tabindex="-1">7.5 示例代码 <a class="header-anchor" href="#_7-5-示例代码" aria-label="Permalink to &quot;7.5 示例代码&quot;">​</a></h3><p>以下是一个示例，演示如何从键盘输入数据：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">import</span><span style="color:#93A1A1;font-weight:bold;"> java.util.Scanner</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">public</span><span style="color:#93A1A1;font-weight:bold;"> class</span><span style="color:#CB4B16;"> InputExample</span><span style="color:#839496;"> {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    public</span><span style="color:#93A1A1;font-weight:bold;"> static</span><span style="color:#93A1A1;font-weight:bold;"> void</span><span style="color:#268BD2;"> main</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">String</span><span style="color:#839496;">[] args) {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        Scanner</span><span style="color:#268BD2;"> scanner</span><span style="color:#859900;"> =</span><span style="color:#859900;"> new</span><span style="color:#268BD2;"> Scanner</span><span style="color:#839496;">(</span><span style="color:#268BD2;">System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">in</span><span style="color:#839496;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 读取字符串</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;请输入你的名字: &quot;</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        String</span><span style="color:#268BD2;"> name</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> scanner</span><span style="color:#839496;">.</span><span style="color:#268BD2;">nextLine</span><span style="color:#839496;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 读取整数</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;请输入你的年龄: &quot;</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        int</span><span style="color:#268BD2;"> age</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> scanner</span><span style="color:#839496;">.</span><span style="color:#268BD2;">nextInt</span><span style="color:#839496;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 读取浮点数</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;请输入你的身高 (米): &quot;</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">        double</span><span style="color:#268BD2;"> height</span><span style="color:#859900;"> =</span><span style="color:#268BD2;"> scanner</span><span style="color:#839496;">.</span><span style="color:#268BD2;">nextDouble</span><span style="color:#839496;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 输出结果</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;名字: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> name);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;年龄: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> age);</span></span>
<span class="line"><span style="color:#268BD2;">        System</span><span style="color:#839496;">.</span><span style="color:#268BD2;">out</span><span style="color:#839496;">.</span><span style="color:#268BD2;">println</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;身高: &quot;</span><span style="color:#859900;"> +</span><span style="color:#839496;"> height </span><span style="color:#859900;">+</span><span style="color:#2AA198;"> &quot; 米&quot;</span><span style="color:#839496;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">        // 关闭 scanner</span></span>
<span class="line"><span style="color:#268BD2;">        scanner</span><span style="color:#839496;">.</span><span style="color:#268BD2;">close</span><span style="color:#839496;">();</span></span>
<span class="line"><span style="color:#839496;">    }</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="_7-6-注意事项" tabindex="-1">7.6 注意事项 <a class="header-anchor" href="#_7-6-注意事项" aria-label="Permalink to &quot;7.6 注意事项&quot;">​</a></h3><ul><li><p><strong>输入类型</strong>: 确保输入的数据类型与读取方法匹配。否则，可能会抛出 <code>InputMismatchException</code> 异常。</p></li><li><p><strong>关闭 <code>Scanner</code></strong>: 在不再使用 <code>Scanner</code> 对象时，应该调用 <code>scanner.close()</code> 方法关闭它，以释放资源。</p></li><li><p><strong>处理输入异常</strong>: 可以使用异常处理机制（如 <code>try-catch</code>）来处理输入错误，确保程序的健壮性。</p></li></ul><h1 id="_8-运算符与表达式-此部分建议看书本p35" tabindex="-1"><u style="text-decoration:underline;text-decoration-color:deepskyblue;">8.运算符与表达式(此部分建议看书本P35)</u> <a class="header-anchor" href="#_8-运算符与表达式-此部分建议看书本p35" aria-label="Permalink to &quot;&lt;u style=&quot;text-decoration: underline; text-decoration-color: deepskyblue;&quot;&gt;8.运算符与表达式(此部分建议看书本P35)&lt;/u&gt;&quot;">​</a></h1><h3 id="_8-1-运算符" tabindex="-1">8.1 运算符 <a class="header-anchor" href="#_8-1-运算符" aria-label="Permalink to &quot;8.1 运算符&quot;">​</a></h3><p>运算符是用于执行操作的符号。Java 提供了多种类型的运算符，主要包括：</p><h4 id="_8-1-1-算术运算符" tabindex="-1">8.1.1 算术运算符 <a class="header-anchor" href="#_8-1-1-算术运算符" aria-label="Permalink to &quot;8.1.1 算术运算符&quot;">​</a></h4><p>用于执行基本的数学运算：</p><ul><li><code>+</code> : 加法</li><li><code>-</code> : 减法</li><li><code>*</code> : 乘法</li><li><code>/</code> : 除法</li><li><code>%</code> : 取模（求余数）</li></ul><h4 id="_8-1-2-关系运算符" tabindex="-1">8.1.2 关系运算符 <a class="header-anchor" href="#_8-1-2-关系运算符" aria-label="Permalink to &quot;8.1.2 关系运算符&quot;">​</a></h4><p>用于比较两个值，返回布尔类型（<code>true</code> 或 <code>false</code>）：</p><ul><li><code>==</code> : 等于</li><li><code>!=</code> : 不等于</li><li><code>&gt;</code> : 大于</li><li><code>&lt;</code> : 小于</li><li><code>&gt;=</code> : 大于或等于</li><li><code>&lt;=</code> : 小于或等于</li></ul><h4 id="_8-1-3-逻辑运算符" tabindex="-1">8.1.3 逻辑运算符 <a class="header-anchor" href="#_8-1-3-逻辑运算符" aria-label="Permalink to &quot;8.1.3 逻辑运算符&quot;">​</a></h4><p>用于连接布尔表达式：</p><ul><li><p><strong><code>&amp;&amp;</code>（逻辑与）</strong>:</p><ul><li>当且仅当两个操作数都为 <code>true</code> 时，结果为 <code>true</code>。</li><li>示例：<code>true &amp;&amp; false</code> 的结果为 <code>false</code>。</li></ul></li><li><p><strong><code>||</code>（逻辑或）</strong>:</p><ul><li>只要有一个操作数为 <code>true</code>，结果为 <code>true</code>。</li><li>示例：<code>true || false</code> 的结果为 <code>true</code>。</li></ul></li><li><p><strong><code>!</code>（逻辑非）</strong>:</p><ul><li>反转操作数的布尔值，<code>true</code> 变为 <code>false</code>，反之亦然。</li><li>示例：<code>!true</code> 的结果为 <code>false</code>。</li></ul></li><li><p><strong><code>&amp;</code>（逻辑与）</strong>:</p><ul><li>类似于 <code>&amp;&amp;</code>，但无短路行为，两个操作数都被计算。</li><li>示例：<code>true &amp; false</code> 的结果为 <code>false</code>。</li></ul></li><li><p><strong><code>|</code>（逻辑或）</strong>:</p><ul><li>类似于 <code>||</code>，但无短路行为，两个操作数都被计算。</li><li>示例：<code>true | false</code> 的结果为 <code>true</code>。</li></ul></li><li><p><strong><code>^</code>（逻辑异或）</strong>:</p><ul><li>当且仅当一个操作数为 <code>true</code>，另一个为 <code>false</code> 时，结果为 <code>true</code>。</li><li>示例：<code>true ^ false</code> 的结果为 <code>true</code>。</li></ul></li></ul><h4 id="_8-1-4-位运算符" tabindex="-1">8.1.4 位运算符 <a class="header-anchor" href="#_8-1-4-位运算符" aria-label="Permalink to &quot;8.1.4 位运算符&quot;">​</a></h4><p>用于对二进制位进行操作：</p><ul><li><p><strong><code>&amp;</code>（按位与）</strong>:</p><ul><li>对应位都为 <code>1</code> 时，结果位为 <code>1</code>。</li><li>示例：<code>5 &amp; 3</code>（0101 &amp; 0011）结果为 <code>1</code>（0001）。</li></ul></li><li><p><strong><code>|</code>（按位或）</strong>:</p><ul><li>只要有一个对应位为 <code>1</code>，结果位为 <code>1</code>。</li><li>示例：<code>5 | 3</code>（0101 | 0011）结果为 <code>7</code>（0111）。</li></ul></li><li><p><strong><code>^</code>（按位异或）</strong>:</p><ul><li>对应位不同则结果位为 <code>1</code>。</li><li>示例：<code>5 ^ 3</code>（0101 ^ 0011）结果为 <code>6</code>（0110）。</li></ul></li><li><p><strong><code>~</code>（按位取反）</strong>:</p><ul><li>反转每一位，<code>0</code> 变为 <code>1</code>，<code>1</code> 变为 <code>0</code>。</li><li>示例：<code>~5</code>（0101）结果为 <code>-6</code>（1111...1010）。</li></ul></li><li><p><strong><code>&lt;&lt;</code>（左移）</strong>:</p><ul><li>将操作数的位向左移动指定的位数，右侧补 <code>0</code>。</li><li>示例：<code>5 &lt;&lt; 1</code>（0101）结果为 <code>10</code>（1010）。</li></ul></li><li><p><strong><code>&gt;&gt;</code>（右移）</strong>:</p><ul><li>将操作数的位向右移动指定的位数，符号位补充。</li><li>示例：<code>5 &gt;&gt; 1</code>（0101）结果为 <code>2</code>（0010）。</li></ul></li><li><p><strong><code>&gt;&gt;&gt;</code>（无符号右移）</strong>:</p><ul><li>将操作数的位向右移动指定的位数，左侧补 <code>0</code>。</li><li>示例：<code>-5 &gt;&gt;&gt; 1</code> 结果为 <code>2147483645</code>。</li></ul></li></ul><h4 id="_8-1-5-赋值运算符" tabindex="-1">8.1.5 赋值运算符 <a class="header-anchor" href="#_8-1-5-赋值运算符" aria-label="Permalink to &quot;8.1.5 赋值运算符&quot;">​</a></h4><p>用于给变量赋值：</p><ul><li><code>=</code> : 赋值</li><li><code>+=</code> : 加并赋值</li><li><code>-=</code> : 减并赋值</li><li><code>*=</code> : 乘并赋值</li><li><code>/=</code> : 除并赋值</li><li><code>%=</code> : 取模并赋值</li></ul><h4 id="_8-1-6-条件运算符" tabindex="-1">8.1.6 条件运算符 <a class="header-anchor" href="#_8-1-6-条件运算符" aria-label="Permalink to &quot;8.1.6 条件运算符&quot;">​</a></h4><p>也称为三元运算符，用于简化 <code>if-else</code> 语句：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>条件 ? 表达式1 : 表达式2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_8-2-表达式" tabindex="-1">8.2 表达式 <a class="header-anchor" href="#_8-2-表达式" aria-label="Permalink to &quot;8.2 表达式&quot;">​</a></h3><p>表达式是由运算符和操作数组成的一段代码，计算后返回一个值。表达式可以是简单的，也可以是复杂的。</p><h4 id="_8-2-1-示例表达式" tabindex="-1">8.2.1 示例表达式 <a class="header-anchor" href="#_8-2-1-示例表达式" aria-label="Permalink to &quot;8.2.1 示例表达式&quot;">​</a></h4><ul><li><p>算术表达式：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>int result = (5 + 3) * 2; // 结果为 16</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>关系表达式：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>boolean isEqual = (5 == 5); // 结果为 true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>逻辑表达式：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>boolean result = (5 &gt; 3) &amp;&amp; (3 &lt; 10); // 结果为 true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>条件表达式：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>int max = (a &gt; b) ? a : b; // 返回 a 和 b 中的较大值</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><h3 id="_8-3-示例代码" tabindex="-1">8.3 示例代码 <a class="header-anchor" href="#_8-3-示例代码" aria-label="Permalink to &quot;8.3 示例代码&quot;">​</a></h3><p>以下是一个示例，展示运算符与表达式的使用：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>public class OperatorExample {</span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        int a = 10, b = 20;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 算术运算</span></span>
<span class="line"><span>        int sum = a + b;</span></span>
<span class="line"><span>        System.out.println(&quot;Sum: &quot; + sum);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 关系运算</span></span>
<span class="line"><span>        boolean isGreater = a &gt; b;</span></span>
<span class="line"><span>        System.out.println(&quot;Is A greater than B? &quot; + isGreater);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 逻辑运算</span></span>
<span class="line"><span>        boolean result = (a &lt; b) &amp;&amp; (b &gt; 15);</span></span>
<span class="line"><span>        System.out.println(&quot;Result of logical operation: &quot; + result);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // 条件运算</span></span>
<span class="line"><span>        int max = (a &gt; b) ? a : b;</span></span>
<span class="line"><span>        System.out.println(&quot;Max value: &quot; + max);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><h3 id="_8-4优先级表" tabindex="-1">8.4优先级表 <a class="header-anchor" href="#_8-4优先级表" aria-label="Permalink to &quot;8.4优先级表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优先级</th><th>运算符</th><th>描述</th><th>结合性</th></tr></thead><tbody><tr><td>1</td><td><code>()</code></td><td>括号</td><td>从左到右</td></tr><tr><td>2</td><td><code>++</code> <code>--</code></td><td>前置自增自减</td><td>从右到左</td></tr><tr><td>3</td><td><code>!</code> <code>~</code></td><td>逻辑非 按位取反</td><td>从右到左</td></tr><tr><td>4</td><td><code>*</code> <code>/</code> <code>%</code></td><td>乘法 除法 取模</td><td>从左到右</td></tr><tr><td>5</td><td><code>+</code> <code>-</code></td><td>加法 减法</td><td>从左到右</td></tr><tr><td>6</td><td><code>&lt;&lt;</code> <code>&gt;&gt;</code> <code>&gt;&gt;&gt;</code></td><td>左移 右移 无符号右移</td><td>从左到右</td></tr><tr><td>7</td><td><code>&lt;</code> <code>&lt;=</code> <code>&gt;</code> <code>&gt;=</code></td><td>关系运算</td><td>从左到右</td></tr><tr><td>8</td><td><code>==</code> <code>!=</code></td><td>等于 不等于</td><td>从左到右</td></tr><tr><td>9</td><td><code>&amp;</code></td><td>按位与</td><td>从左到右</td></tr><tr><td>10</td><td><code>^</code></td><td>按位异或</td><td>从左到右</td></tr><tr><td>11</td><td><code>｜</code></td><td>按位或</td><td>从左到右</td></tr><tr><td>12</td><td><code>&amp;&amp;</code></td><td>逻辑与</td><td>从左到右</td></tr><tr><td>13</td><td><code>||</code></td><td>逻辑或</td><td>从左到右</td></tr><tr><td>14</td><td><code>?:</code></td><td>条件运算符</td><td>从右到左</td></tr><tr><td>15</td><td><code>=</code> <code>+=</code> <code>-=</code></td><td>赋值 复合赋值</td><td>从右到左</td></tr><tr><td>16</td><td><code>,</code></td><td>逗号</td><td>从左到右</td></tr></tbody></table><blockquote><p><strong>算术运算符</strong>（如 <code>*</code>, <code>/</code>）的优先级高于 <strong>关系运算符</strong>（如 <code>&lt;</code>, <code>&gt;</code>, <code>==</code>）。 <strong>逻辑运算符</strong>（如 <code>&amp;&amp;</code>, <code>||</code>）的优先级低于 <strong>位运算符</strong>（如 <code>&amp;</code>, <code>|</code>）。</p></blockquote><hr>`,151)]))}const y=a(l,[["render",o]]);export{b as __pageData,y as default};
